import{_ as n,C as t,o as s,c as o,E as r,a2 as l}from"./chunks/framework.BOeh4kYD.js";const d="/joinwell52/assets/authority-scope-20260910/01-secret-route.figure.en.png",y=JSON.parse('{"title":"The Credential File Disappeared. Did Access Disappear Too?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The Credential File Disappeared. Did Access Disappear Too?","date":"2026-09-10","published_date":"2026-09-10","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"The Credential File Disappeared. Did Access Disappear Too?","summary":"A pinned-source experiment shows why fewer credential files do not necessarily mean fewer secrets available to the receiving process.","cover":"/assets/authority-scope-20260910/01-secret-route.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded pinned-source seam experiments; not full-system validation","pageClass":"authority-scope-article"},"headers":[],"relativePath":"en/engineering/2026-09-10-secret-route.md","filePath":"en/engineering/2026-09-10-secret-route.md","lastUpdated":1789010602000}'),c={name:"en/engineering/2026-09-10-secret-route.md"};function h(p,e,u,g,m,f){const a=t("ArticleCover"),i=t("ArticleTableScroll");return s(),o("div",null,[r(a,{image:"/assets/authority-scope-20260910/01-secret-route.cover-v1.png",kicker:"Open-source Engineering · Experiments",title:"The Credential File Disappeared. Did Access Disappear Too?",summary:"A pinned-source experiment shows why fewer credential files do not necessarily mean fewer secrets available to the receiving process.",version:"2026-09-10",languageHref:"/zh/engineering/2026-09-10-secret-route",languageLabel:"中文"}),r(i,{language:"en"}),e[0]||(e[0]=l('<h1 id="the-credential-file-disappeared-did-access-disappear-too" tabindex="-1">The Credential File Disappeared. Did Access Disappear Too? <a class="header-anchor" href="#the-credential-file-disappeared-did-access-disappear-too" aria-label="Permalink to &quot;The Credential File Disappeared. Did Access Disappear Too?&quot;">​</a></h1><p>A credential fix reduced file-materialization callbacks from four to zero. That looks reassuring—until the receiving process is inspected. In our controlled experiment, the same four synthetic credential blobs appeared as environment variables.</p><p>There was no mysterious bypass. The values had changed delivery routes. The question is what “credential isolation” promises: a restriction on where files are created, or a restriction on which values a process can obtain.</p><h2 id="a-useful-fix-with-a-narrower-contract" tabindex="-1">A useful fix with a narrower contract <a class="header-anchor" href="#a-useful-fix-with-a-narrower-contract" aria-label="Permalink to &quot;A useful fix with a narrower contract&quot;">​</a></h2><p>OpenHands Agent SDK can launch different agent programs through ACP, a protocol connecting an agent client to an execution program. Those programs use different authentication mechanisms, including environment variables and credential files.</p><p><a href="https://github.com/OpenHands/software-agent-sdk/pull/4927" target="_blank" rel="noreferrer">PR #4927</a> narrows file-secret handling by provider ownership. The default configuration combines multiple providers&#39; file rules; the proposed change avoids materializing unrelated providers&#39; files when starting one particular program. That is a useful correction to credential representation and directory configuration.</p><p>File rules, however, are not a secret allow-list. The startup path also exports registry secrets as ordinary environment variables, excluding those handled as files. Narrowing the file set narrows this exclusion set too. A value removed from one route can consequently reappear on the other.</p><p>This does not make the patch a failed implementation of its stated goal. It means reviewers should not add a stronger promise—“all other providers&#39; secrets become inaccessible”—that the change does not establish.</p><h2 id="observe-the-recipient-not-just-the-writer" tabindex="-1">Observe the recipient, not just the writer <a class="header-anchor" href="#observe-the-recipient-not-just-the-writer" aria-label="Permalink to &quot;Observe the recipient, not just the writer&quot;">​</a></h2><p>We pinned the PR&#39;s base and head revisions and executed its original filtering methods, environment-conflict method, and contiguous environment-construction slice. Both revisions used registry metadata extracted from the head to isolate the handling change. Provider identity was fixture-supplied; actual command detection was not tested. All inputs were synthetic strings.</p><p>File materialization was a recording fixture: the file-side numbers below count callbacks, not authentication files actually written to disk. The assembled environment was passed to a real Python child process, which returned variable names only. It did not launch a model or attempt authentication.</p><table tabindex="0"><thead><tr><th>Revision and recipient</th><th style="text-align:right;">File-side callbacks</th><th style="text-align:right;">Four credential-blob variables visible to child</th></tr></thead><tbody><tr><td>Base, Claude</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td></tr><tr><td>Proposed head, Claude</td><td style="text-align:right;">0</td><td style="text-align:right;">4</td></tr><tr><td>Base, Codex</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td></tr><tr><td>Proposed head, Codex</td><td style="text-align:right;">1</td><td style="text-align:right;">3</td></tr><tr><td>Proposed head, unrecognized provider</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td></tr></tbody></table><p>Both rounds produced the same results. The four blobs correspond to registered file credentials for Codex, Gemini, Kimi and Pi. Codex retained its own file route while three other blobs became ordinary environment variables. An unrecognized provider retained every file specification. Those branches cannot all be summarized as “only this provider&#39;s credentials remain.”</p><p><img src="'+d+'" alt="File-side and environment-side observations"></p><p><em>Figure 1. The figure uses our local seam-test observations. It establishes delivery of synthetic values through the tested construction path, not their use by a real CLI or disclosure over a network. Source: saved rounds 1 and 2 of our pinned-source experiments.</em></p><h2 id="an-empty-list-can-have-an-authentication-exception" tabindex="-1">An empty list can have an authentication exception <a class="header-anchor" href="#an-empty-list-can-have-an-authentication-exception" aria-label="Permalink to &quot;An empty list can have an authentication exception&quot;">​</a></h2><p><a href="https://github.com/OpenHands/software-agent-sdk/pull/4931" target="_blank" rel="noreferrer">Draft PR #4931</a> addresses a different layer: profile-level restrictions on secret names received by a conversation. Filtering the registry can narrow both downstream delivery routes.</p><p>We placed that PR&#39;s original filtering functions before the earlier environment slice. This is explicitly a laboratory composition of two separate PRs, not a merged SDK release or a server integration test.</p><p>Given the same six synthetic inputs, the Claude ACP profile produced:</p><table tabindex="0"><thead><tr><th><code>secret_refs</code></th><th>Names retained in the registry</th></tr></thead><tbody><tr><td><code>null</code></td><td>All six supplied names</td></tr><tr><td><code>[]</code></td><td>The provider&#39;s <code>ANTHROPIC_API_KEY</code></td></tr><tr><td><code>[PROD_DB_URL]</code></td><td>The database variable and provider authentication variable</td></tr></tbody></table><p>The empty list removed business secrets while retaining an explicit authentication exception. The program still needs a way to authenticate. As a separate control, we executed only the ordinary OpenHands profile&#39;s empty-list filter and obtained an empty set; that control did not pass through ACP startup.</p><p>An interface therefore needs to explain what its empty list means. “No selected business secrets” and “this process receives no secrets at all” are materially different expectations.</p><h2 id="the-registry-is-not-every-input-channel" tabindex="-1">The registry is not every input channel <a class="header-anchor" href="#the-registry-is-not-every-input-channel" aria-label="Permalink to &quot;The registry is not every input channel&quot;">​</a></h2><p>The tested startup slice also merges the host environment. A separate synthetic marker placed on that route remained visible to the child in every ACP scenario, including the empty-list case.</p><p>This is not a production leak report. It shows that a registry filter cannot constrain an input that bypasses the registry. The draft explicitly leaves host-environment inheritance outside its scope.</p><p>A stronger acceptance test begins by defining the business secrets and authentication materials authorized for a provider and run, then observes the actual environment and file capabilities at the receiving process boundary. Representation changes should follow that selection. Unknown-provider behavior needs its own explicit policy as well.</p><p>Our experiment did not exercise the complete SDK, a real ACP handshake, authentication, or server request filtering. Its conclusion is narrower: <strong>a disappearing credential file is insufficient evidence of disappearing access. Trace every delivery route for the same secret and inspect the set the recipient actually receives.</strong></p><p><a href="/joinwell52/zh/engineering/2026-09-10-secret-route">中文</a> · <a href="/joinwell52/en/research/evidence/2026-09-10-authority-scope">Methods, pinned revisions and raw results</a></p>',28))])}const b=n(c,[["render",h]]);export{y as __pageData,b as default};
